  '{"python":"# Problem 1: Target Pair\n# Input format:\n#   Line 1: n target\n#   Line 2: n integers a[0..n-1]\n# Output: YES or NO\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 1: Target Pair\n// Input format:\n//   Line 1: n target\n//   Line 2: n integers a[0..n-1]\n// Output: YES or NO\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":600,"python":500}'::jsonb),
('bracket-check', 2, 'Bracket Check', 'easy', array['stack', 'strings']::text[], 'stack',
  '["A configuration file uses three kinds of brackets: round `()`, square `[]` and curly `{}`. Before the file is loaded, a checker confirms that the brackets are balanced.","A string is balanced when every opening bracket is closed by the same kind of bracket, brackets close in the reverse order they were opened, and no closing bracket appears without a matching opener."]'::jsonb, '["A single line containing a nonempty string made only of the characters `()[]{}`."]'::jsonb, '["Print `YES` if the string is balanced, otherwise print `NO`."]'::jsonb, '["1 ≤ length of the string ≤ 200000","Nesting can be up to 100000 levels deep, so avoid recursion that uses one call per bracket."]'::jsonb,
  '[{"input":"{[()]}\n","output":"YES\n","explanation":"Each bracket closes in reverse order of opening."},{"input":"(]\n","output":"NO\n","explanation":"A round bracket is closed by a square bracket."}]'::jsonb,
  '{"python":"# Problem 2: Bracket Check\n# Input format:\n#   Line 1: a string s made of the characters ()[]{}\n# Output: YES or NO\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 2: Bracket Check\n// Input format:\n//   Line 1: a string s made of the characters ()[]{}\n// Output: YES or NO\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":500,"python":550}'::jsonb),
('first-occurrence', 3, 'First Occurrence', 'easy', array['binary-search', 'arrays']::text[], 'binary-search',
  '["A sensor log stores readings in nondecreasing order. Given a reading `x`, find the first position in the log where `x` appears.","Positions are zero-based: the first reading is at position 0."]'::jsonb, '["The first line contains two integers `n` and `x`.","The second line contains `n` integers in nondecreasing order."]'::jsonb, '["Print the smallest index `i` with `a[i] = x`, or `-1` if `x` does not appear."]'::jsonb, '["1 ≤ n ≤ 100000","-10^9 ≤ a[i], x ≤ 10^9","a[0] ≤ a[1] ≤ … ≤ a[n-1]"]'::jsonb,
  '[{"input":"6 4\n1 2 4 4 4 8\n","output":"2\n","explanation":"The value 4 first appears at index 2."},{"input":"5 3\n1 2 4 5 6\n","output":"-1\n","explanation":"3 would sit between 2 and 4 but is not present."}]'::jsonb,
  '{"python":"# Problem 3: First Occurrence\n# Input format:\n#   Line 1: n x\n#   Line 2: n integers in nondecreasing order\n# Output: the first zero-based index of x, or -1\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 3: First Occurrence\n// Input format:\n//   Line 1: n x\n//   Line 2: n integers in nondecreasing order\n// Output: the first zero-based index of x, or -1\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":1200,"python":500}'::jsonb),
