  '["A habit tracker records each day as `1` (habit done) or `0` (missed). Find the longest run of consecutive days on which the habit was done."]'::jsonb, '["The first line contains an integer `n`.","The second line contains `n` binary digits (`0` or `1`) separated by spaces."]'::jsonb, '["Print the length of the longest contiguous run of `1` values. Print `0` if there are none."]'::jsonb, '["1 ≤ n ≤ 150000","Every digit is 0 or 1."]'::jsonb,
  '[{"input":"7\n1 1 0 1 1 1 0\n","output":"3\n","explanation":"Days 3 to 5 form a run of three."},{"input":"5\n0 1 0 1 0\n","output":"1\n","explanation":"Every run of ones has length one."}]'::jsonb,
