('maximum-segment-sum', 5, 'Maximum Segment Sum', 'medium', array['dynamic-programming', 'arrays']::text[], 'dynamic-programming',
  '["A delivery route reports the profit (possibly negative) of each stop. The company may run any nonempty contiguous part of the route. Find the largest total profit that a contiguous segment can earn.","The segment must contain at least one stop, so when every profit is negative the answer is the largest single profit."]'::jsonb, '["The first line contains an integer `n`.","The second line contains `n` integers."]'::jsonb, '["Print the maximum sum of a nonempty contiguous segment."]'::jsonb, '["1 ≤ n ≤ 80000","-10^9 ≤ a[i] ≤ 10^9","The answer can be as large as 8·10^13. Python integers and JavaScript numbers (exact up to 2^53) represent it exactly."]'::jsonb,
  '[{"input":"6\n-2 3 -1 4 -5 2\n","output":"6\n","explanation":"The segment 3, -1, 4 has sum 6."},{"input":"5\n1 2 3 4 5\n","output":"15\n","explanation":"Taking every stop is best."}]'::jsonb,
  '{"python":"# Problem 5: Maximum Segment Sum\n# Input format:\n#   Line 1: n\n#   Line 2: n integers\n# Output: the largest sum of a nonempty contiguous segment (may need 64-bit)\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 5: Maximum Segment Sum\n// Input format:\n//   Line 1: n\n//   Line 2: n integers\n// Output: the largest sum of a nonempty contiguous segment (may need 64-bit)\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":1100,"python":500}'::jsonb),
