('merge-maintenance-slots', 7, 'Merge Maintenance Slots', 'medium', array['sorting', 'intervals']::text[], 'intervals',
  '["Several teams booked maintenance windows on the same server. Each booking is a closed interval `[l, r]` of integer minutes, which includes both endpoints.","Combine bookings that overlap into a single window. Two bookings overlap when they share at least one minute, so `[1, 3]` and `[3, 5]` merge into `[1, 5]`. Bookings that only touch as neighbours, such as `[1, 2]` and `[3, 4]`, stay separate.","Print the merged windows sorted by their left endpoint."]'::jsonb, '["The first line contains an integer `n`.","Each of the next `n` lines contains two integers `l r`."]'::jsonb, '["On the first line print `k`, the number of merged windows.","Then print `k` lines, each with `l r` for one merged window, sorted by `l`."]'::jsonb, '["1 ≤ n ≤ 25000","-10^9 ≤ l ≤ r ≤ 10^9","Bookings are given in any order. The output can contain up to 25001 lines, so build it efficiently (for example by joining strings) instead of printing one value at a time with flushing."]'::jsonb,
  '[{"input":"4\n5 7\n1 3\n3 5\n9 10\n","output":"2\n1 7\n9 10\n","explanation":"[1,3], [3,5] and [5,7] chain into [1,7]."},{"input":"3\n1 2\n3 4\n2 2\n","output":"2\n1 2\n3 4\n","explanation":"[2,2] lies inside [1,2]; [3,4] only touches it and stays separate."}]'::jsonb,
  '{"python":"# Problem 7: Merge Maintenance Slots\n# Input format:\n#   Line 1: n\n#   Next n lines: l r (closed interval)\n# Output: k, then k lines ''l r'' sorted by l\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 7: Merge Maintenance Slots\n// Input format:\n//   Line 1: n\n//   Next n lines: l r (closed interval)\n// Output: k, then k lines ''l r'' sorted by l\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":1100,"python":500}'::jsonb),
('minimum-coins', 8, 'Minimum Coins', 'medium', array['dynamic-programming']::text[], 'dynamic-programming',
  '["A vending machine gives change using an unlimited supply of coins of a few distinct denominations. Find the fewest coins needed to pay an amount exactly.","If the amount cannot be formed, report `-1`. Paying an amount of zero needs zero coins."]'::jsonb, '["The first line contains two integers `n` and `amount`.","The second line contains `n` distinct positive integers, the coin denominations."]'::jsonb, '["Print the minimum number of coins whose values sum to `amount`, or `-1` if it is impossible."]'::jsonb, '["1 ≤ n ≤ 30","0 ≤ amount ≤ 10000","1 ≤ denomination ≤ 10000, all denominations are distinct."]'::jsonb,
  '[{"input":"3 6\n1 3 4\n","output":"2\n","explanation":"3 + 3 uses two coins. Taking the largest coin first (4 + 1 + 1) uses three."},{"input":"3 11\n1 2 5\n","output":"3\n","explanation":"5 + 5 + 1."}]'::jsonb,
  '{"python":"# Problem 8: Minimum Coins\n# Input format:\n#   Line 1: n amount\n#   Line 2: n distinct positive denominations\n# Output: the minimum number of coins, or -1\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 8: Minimum Coins\n// Input format:\n//   Line 1: n amount\n//   Line 2: n distinct positive denominations\n// Output: the minimum number of coins, or -1\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":500,"python":800}'::jsonb),
('island-count', 9, 'Island Count', 'medium', array['grids', 'bfs', 'dfs', 'graphs']::text[], 'grids',
  '["A satellite map is a grid of cells, where `1` is land and `0` is water. An island is a group of land cells connected horizontally or vertically. Cells that touch only at a corner (diagonally) are not connected.","Count the islands on the map."]'::jsonb, '["The first line contains two integers `r` and `c`.","Each of the next `r` lines contains a string of exactly `c` characters, each `0` or `1`."]'::jsonb, '["Print the number of islands."]'::jsonb, '["1 ≤ r, c ≤ 400","A single island can contain all 160000 cells and form a long winding path. Recursive DFS may overflow the call stack; an explicit queue or stack is safer."]'::jsonb,
  '[{"input":"3 4\n1100\n0101\n0001\n","output":"2\n","explanation":"The top-left block is one island; the cells in column 3 form another."},{"input":"4 5\n11000\n11000\n00100\n00011\n","output":"3\n","explanation":"Three groups; the middle cell only touches the others diagonally."}]'::jsonb,
  '{"python":"# Problem 9: Island Count\n# Input format:\n#   Line 1: r c\n#   Next r lines: a string of c characters, each 0 or 1\n# Output: the number of 4-directionally connected groups of 1s\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 9: Island Count\n// Input format:\n//   Line 1: r c\n//   Next r lines: a string of c characters, each 0 or 1\n// Output: the number of 4-directionally connected groups of 1s\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":700,"python":1000}'::jsonb),
('next-warmer-day', 10, 'Next Warmer Day', 'medium', array['monotonic-stack', 'stack', 'arrays']::text[], 'monotonic-stack',
  '["A weather station recorded one temperature per day. For each day, find how many days you would have to wait for a strictly warmer temperature.","If no later day is strictly warmer, the answer for that day is `0`."]'::jsonb, '["The first line contains an integer `n`.","The second line contains `n` integers, the temperatures in order."]'::jsonb, '["Print `n` integers separated by spaces. The `i`-th integer is `j - i` for the smallest `j > i` with `t[j] > t[i]`, or `0` if there is no such day."]'::jsonb, '["1 ≤ n ≤ 80000","-10^9 ≤ t[i] ≤ 10^9","The output has up to 80000 numbers; build it in one string instead of printing each number separately."]'::jsonb,
  '[{"input":"5\n70 70 72 68 75\n","output":"2 1 2 1 0\n","explanation":"Equal temperatures are not warmer, so day 0 waits two days for 72."},{"input":"4\n30 40 50 60\n","output":"1 1 1 0\n","explanation":"Each day is followed by a warmer one, except the last."}]'::jsonb,
  '{"python":"# Problem 10: Next Warmer Day\n# Input format:\n#   Line 1: n\n#   Line 2: n temperatures\n# Output: n integers separated by spaces: days to wait for a strictly warmer day, or 0\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 10: Next Warmer Day\n// Input format:\n//   Line 1: n\n//   Line 2: n temperatures\n// Output: n integers separated by spaces: days to wait for a strictly warmer day, or 0\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":1100,"python":500}'::jsonb),
('cheapest-route', 11, 'Cheapest Route', 'hard', array['graphs', 'shortest-path', 'heap']::text[], 'graphs',
  '["A courier network has `n` hubs numbered `1` to `n` and `m` one-way roads. Each road has a toll. Find the cheapest total toll for travelling from hub `s` to hub `t`.","Roads are directed: a road `u v w` can only be used from `u` to `v`. There may be several roads between the same pair of hubs, roads from a hub to itself, and roads with toll `0`. Travelling from a hub to itself costs `0`."]'::jsonb, '["The first line contains four integers `n m s t`.","Each of the next `m` lines contains three integers `u v w`: a road from `u` to `v` with toll `w`."]'::jsonb, '["Print the minimum total toll from `s` to `t`, or `-1` if `t` cannot be reached."]'::jsonb, '["1 ≤ n ≤ 20000","0 ≤ m ≤ 40000","1 ≤ s, t, u, v ≤ n","0 ≤ w ≤ 10^9","A route cost can reach about 2·10^13. Python integers and JavaScript numbers (exact up to 2^53) represent it exactly."]'::jsonb,
  '[{"input":"4 5 1 4\n1 2 2\n1 3 8\n2 3 1\n3 4 3\n2 4 9\n","output":"6\n","explanation":"1 → 2 → 3 → 4 costs 2 + 1 + 3."},{"input":"3 3 1 3\n1 2 4\n2 3 4\n1 3 10\n","output":"8\n","explanation":"Two cheap roads beat the direct road."}]'::jsonb,
  '{"python":"# Problem 11: Cheapest Route\n# Input format:\n#   Line 1: n m s t\n#   Next m lines: u v w (directed road u -> v with toll w)\n# Output: the minimum total toll from s to t, or -1 (may need 64-bit)\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 11: Cheapest Route\n// Input format:\n//   Line 1: n m s t\n//   Next m lines: u v w (directed road u -> v with toll w)\n// Output: the minimum total toll from s to t, or -1 (may need 64-bit)\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":1150,"python":500}'::jsonb),
('minimum-cover-window', 12, 'Minimum Cover Window', 'hard', array['sliding-window', 'strings', 'hash-map']::text[], 'sliding-window',
  '["You are given a long text `S` and a short pattern `T`. Find the shortest contiguous substring of `S` that contains every character of `T`, counting repeats: if `T` has two `a` characters, the substring must contain at least two `a` characters.","If several shortest substrings exist, print the one that starts earliest in `S`. If no substring works, print `-1`."]'::jsonb, '["The first line contains the string `S`.","The second line contains the string `T`.","Both are nonempty and contain only lowercase letters `a`–`z`."]'::jsonb, '["Print the shortest covering substring, or `-1`."]'::jsonb, '["1 ≤ |S| ≤ 200000","1 ≤ |T| ≤ 200000"]'::jsonb,
  '[{"input":"adobecodebanc\nabc\n","output":"banc\n","explanation":"\"banc\" contains a, b and c, and no shorter window does."},{"input":"abcdab\nbd\n","output":"bcd\n","explanation":"\"bcd\" and \"dab\" both have length 3; \"bcd\" starts earlier."}]'::jsonb,
  '{"python":"# Problem 12: Minimum Cover Window\n# Input format:\n#   Line 1: string S\n#   Line 2: string T\n# Output: the shortest substring of S covering T (earliest on ties), or -1\nimport sys\n\n\ndef main():\n    # Every whitespace-separated token from standard input, as strings.\n    data = sys.stdin.read().split()\n\n    # ==== Write your solution below ====\n\n    answer = \"\"\n    print(answer)\n\n\nmain()\n","javascript":"// Problem 12: Minimum Cover Window\n// Input format:\n//   Line 1: string S\n//   Line 2: string T\n// Output: the shortest substring of S covering T (earliest on ties), or -1\nconst data = require(''fs'').readFileSync(0, ''utf8'').split(/\\s+/).filter(Boolean);\n// data holds every whitespace-separated token from standard input, as strings.\n\n// ==== Write your solution below ====\n\nlet answer = '''';\nconsole.log(String(answer));\n"}'::jsonb, '{"javascript":550,"python":1100}'::jsonb)
